import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

const root = path.resolve(import.meta.dirname, "../..");
const read = (file: string) => JSON.parse(readFileSync(path.join(root, file), "utf8"));

type RegistryItem = { name: string; type: string; dependencies: string[]; files: { path: string; type: string }[] };

/**
 * registry.json (shadcn-style) is generated by `npm run docs:generate`; `check:docs` catches drift.
 * These checks keep each item installable: its file exists and every npm package it needs is one an
 * app can install alongside WMDS.
 */
describe("registry.json", () => {
  const registry = read("registry.json") as { name: string; items: RegistryItem[] };
  const pkg = read("package.json");
  const patterns = read("docs/patterns/index.json").patterns as { id: string }[];
  const installable = new Set([pkg.name, ...Object.keys(pkg.peerDependencies), ...Object.keys(pkg.dependencies)]);

  it("has one block per shipped pattern", () => {
    expect(registry.items.map((item) => item.name)).toEqual(patterns.map((pattern) => pattern.id));
    expect(new Set(registry.items.map((item) => item.type))).toEqual(new Set(["registry:block"]));
  });

  it("points every item at a shipped pattern file and installable packages", () => {
    for (const item of registry.items) {
      expect(item.dependencies, item.name).toContain(pkg.name);
      for (const dependency of item.dependencies) expect(installable, `${item.name}: ${dependency}`).toContain(dependency);
      for (const file of item.files) {
        expect(existsSync(path.join(root, file.path)), file.path).toBe(true);
        expect(pkg.files.some((shipped: string) => file.path.startsWith(shipped)), file.path).toBe(true);
      }
    }
  });
});
